import{_ as s,o as e,c as n,a2 as o}from"./chunks/framework.Boholvbs.js";const E=JSON.parse('{"title":"xsync(1)","description":"Parallel file transfers, familiar commands, and progress you can read.","frontmatter":{"title":"xsync(1)","description":"Parallel file transfers, familiar commands, and progress you can read.","manual":"xsync(1)","manualName":"The xsync manual","sectionNumber":"1"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),t={name:"index.md"};function l(r,a,c,p,i,d){return e(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="xsync-1" tabindex="-1">xsync(1) <a class="header-anchor" href="#xsync-1" aria-label="Permalink to &quot;xsync(1)&quot;">​</a></h1><div class="manual-deck"><strong>The xsync manual</strong><p>Parallel file transfers, familiar commands, and progress you can read.</p></div><h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME {#name}&quot;">​</a></h2><p><strong>xsync</strong> — fast, parallel rsync work-alike for macOS and Linux. The executable is named <code>xs</code>.</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS {#synopsis}&quot;">​</a></h2><div class="example-caption">Command forms</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs [OPTION]... SRC [SRC]... DEST</span></span>
<span class="line"><span style="color:#DEDEDE;">xs [OPTION]... SRC</span></span>
<span class="line"><span style="color:#DEDEDE;">xs [OPTION]... SRC [SRC]... [USER@]HOST:DEST</span></span>
<span class="line"><span style="color:#DEDEDE;">xs [OPTION]... [USER@]HOST:SRC [DEST]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION {#description}&quot;">​</a></h2><p>xsync copies file trees locally or over SSH. It uses a C++20 engine, parallel workers, a native transfer protocol, and a live progress display on stderr. A single source argument lists entries instead of copying them.</p><p>Use the options you already know from rsync. Native transfers require the <code>xs</code> executable on both machines. Missing remote support and unsupported options can delegate to a real rsync from PATH; <code>--no-fallback</code> requests native-only execution.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES {#examples}&quot;">​</a></h2><div class="example-caption">Copy a directory’s contents</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><div class="example-caption">Push over SSH</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-azP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> user@host:/backup/src/</span></span></code></pre></div><div class="example-caption">Pull over SSH</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-azP</span><span style="color:#DEDEDE;"> user@host:/data/</span><span style="color:#DEDEDE;"> data/</span></span></code></pre></div><div class="example-caption">Preview a mirror before executing</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-ani</span><span style="color:#DEDEDE;"> --delete</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>The slash on <code>src/</code> means copy its contents. <code>-P</code> enables partial retention and progress. <code>-n</code> previews changes without writing.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS {#options}&quot;">​</a></h2><p>Archive mode, <code>-a</code>, means <code>-rlptgoD</code>. Add <code>-H</code>, <code>-A</code>, or <code>-X</code> when you need hard links, ACLs, or extended attributes. Use <code>-j N</code> to choose worker threads.</p><p>See the <a href="options.html">complete option reference</a>, generated from the executable’s actual <code>--help</code>.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO {#see-also}&quot;">​</a></h2><div class="manual-links"><a href="getting-started.html">Getting started <span>↗</span></a><a href="transfers.html">Transfers &amp; path semantics <span>↗</span></a><a href="progress.html">Progress &amp; output <span>↗</span></a><a href="compatibility.html">Compatibility &amp; boundaries <span>↗</span></a></div>`,25)])])}const y=s(t,[["render",l]]);export{E as __pageData,y as default};
